"""Chapter 6: Methodology and Software Implementation (ResQAI)."""

from . import facts as F
from .blocks import B, CODE, EQ, FIG, H1, H2, H3, N, P, TAB
from .refs import CITE as R


def blocks():
    return [H1("CHAPTER 6: METHODOLOGY AND SOFTWARE IMPLEMENTATION")] + methodology_blocks() + application_blocks()


def _f(path, width=5.6, max_h=4.2, cap=""):
    return FIG(path, cap, F.shot_w(path, width, max_h))


# =====================================================================================================================
def methodology_blocks():
    return overall() + dataset() + preprocessing() + algorithm_choice() + maths() + model_training()


def overall():
    return [
        H2("6.1 Overall Methodology"),
        P("The method has two halves. The first half is what the product does: a reading of eleven features is classified as crash or not, graded, confirmed by the occupant and turned into a located alert. "
          "The second half is how the claims about it were checked, because the project shipped without any evaluation: no metrics file existed, so every number in this report was measured afresh by three scripts written for the purpose. "
          "The method, in order, is:"),
        N("**Define the event and the features.** A crash is a short, large acceleration and rotation spike with a speed drop; harsh braking and normal driving are the look-alikes. Eleven features describe an event (Table below).",
          f"**Generate the data.** `train_models.py` draws {F.N_TOTAL:,} synthetic events of five kinds with a fixed seed (42); there are no real recordings.",
          f"**Split and scale.** An 80/20 split stratified on the accident label gives {F.N_TRAIN:,} training and {F.N_TEST:,} test events; a `StandardScaler` is fitted on the training part only.",
          "**Train two random forests.** One predicts accident / no accident, the other predicts the four-level severity; both use balanced class weights.",
          "**Serve them.** `app.py` loads the pickles once, builds the feature vector of each request, applies the detector-gates-severity rule and returns the label, the probability and the features used.",
          "**Confirm and dispatch.** The browser opens a 15-second countdown for Moderate and Severe results; on expiry it reads the position, ranks the hospitals by great-circle distance and composes the dispatch message.",
          f"**Measure.** The shipped pickles are scored on the held-out {F.N_TEST:,} events and compared with a fresh retrain; a five-seed repeat, four baselines, feature ablations, a noise sweep, a threshold sweep and two out-of-distribution probes follow; the API is timed and 55 unit, edge-case and security checks are run."),
        P("The base paper follows a different method for a different problem: it trains a multi-task FT-Transformer with an uncertainty-weighted loss on 30,442 police-reported crash records to predict injury, fatality and property-loss severity after the event "
          f"[{R['base']}]. ResQAI shares only the idea of grading severity; its input is a motion-sensor reading, its output is an alert decision, and its models are far smaller (Section 6.4)."),
    ]


def dataset():
    ds = F.DS
    kt, ke = ds["kind_counts_total"], ds["kind_counts_test"]
    rows = []
    for k, label in [("normal", "normal driving"), ("harsh_brake", "harsh braking"), ("minor_crash", "minor crash"), ("moderate_crash", "moderate crash"), ("severe_crash", "severe crash")]:
        rows.append([label, f"{kt[k]:,}", f"{kt[k] / F.N_TOTAL * 100:.1f}%", f"{ke[k]:,}", {"normal": "0 (None)", "harsh_brake": "0 (None)", "minor_crash": "1 (Minor)", "moderate_crash": "2 (Moderate)", "severe_crash": "3 (Severe)"}[k]])
    ov = ds["class_overlap"]["acc_magnitude"]
    return [
        H2("6.2 Dataset"),
        P(f"**Source and licence.** The dataset is generated by `make_event` and `generate_dataset` in `train_models.py`; it is self-made, has no external source and no licence restriction. Re-running the generator with `numpy.random.seed(42)` reproduces the same {F.N_TOTAL:,} rows, which the measurement script verified. "
          "The README describes the data as \"crafted to resemble the documented sensor characteristics of real crashes\"; this report treats it as exactly what it is, **synthetic data whose classes were defined by the author of the generator**. "
          "No smartphone recording, vehicle log or public crash-sensor corpus was used, so the first objective (collect smartphone data) is met only in the sense of a generator for the features."),
        P(f"**Composition.** Events are drawn from five kinds with probabilities 0.60, 0.20, 0.10, 0.06 and 0.04. Of the {F.N_TOTAL:,} rows, {F.pct(ds['accident_rate_total'], 2)} are crashes. "
          "The accident label is 1 for the three crash kinds; the severity label is 0 for normal driving and harsh braking and 1, 2 and 3 for the three crash kinds."),
        TAB("Composition of the synthetic dataset", ["Event kind", "Events", "Share", "In the test split", "Severity label"], rows, widths=[1.5, 0.9, 0.8, 1.2, 1.4], align=["l", "r", "r", "r", "l"], size=10),
        P("**Generator parameters.** Every channel of every kind is drawn from a normal or uniform distribution (Table below). A crash spike has a magnitude drawn uniformly from a band that depends on the grade (15 to 28, 28 to 45, 45 to 80 m/s²) and a random direction in the horizontal plane, "
          "so that `acc_x = m cos θ + noise` and `acc_y = m sin θ + noise`; the vertical axis stays near gravity (9.81 m/s²) with a larger spread for harder crashes. Deceleration, rotation noise and jerk all grow with severity."),
        TAB("Generator parameters per event kind (g = 9.81 m/s²; N = normal, U = uniform)", ["Channel", "Normal driving", "Harsh braking", "Minor crash", "Moderate crash", "Severe crash"],
            [["acc x, y (m/s²)", "N(0, 0.4)", "x N(-4.5, 1.2); y N(0, 0.6)", "m cos θ, m sin θ, m ~ U(15, 28), noise 1.5", "m ~ U(28, 45), noise 2", "m ~ U(45, 80), noise 3"],
             ["acc z (m/s²)", "N(g, 0.3)", "N(g, 0.5)", "N(g, 2.0)", "N(g, 3.0)", "N(g, 5.0)"],
             ["gyro x, y, z (rad/s)", "N(0, 0.15)", "N(0, 0.3) / 0.3 / 0.4", "N(0, 1.5)", "N(0, 2.5)", "N(0, 4.0)"],
             ["speed before (km/h)", "U(0, 80)", "U(20, 100)", "U(10, 60)", "U(30, 90)", "U(40, 140)"],
             ["speed change (km/h)", "N(0, 2)", "-U(10, 35)", "-U(10, 40)", "-U(25, 55)", "-U(45, 100)"],
             ["jerk (absolute)", "N(0, 0.5)", "N(6, 2)", "N(20, 5)", "N(35, 8)", "N(60, 12)"]],
            widths=[1.1, 0.8, 1.2, 1.3, 1.0, 1.0], size=8),
        _f(F.fig("f01_feature_separation.png"), 6.0, 3.6, "Distribution of acceleration magnitude by event kind (log scale) and magnitude against jerk: crashes sit well clear of harsh braking."),
        P(f"**What the figure shows.** Normal driving and harsh braking never exceed {ov['harsh_brake'][1]:.1f} m/s² in acceleration magnitude, whereas the weakest crash starts at {ov['minor_crash'][0]:.1f} m/s²: a single threshold near 15 m/s² separates crash from non-crash with no error. "
          f"The severity bands overlap only at their edges (minor and moderate between {ov['moderate_crash'][0]:.1f} and {ov['minor_crash'][1]:.1f} m/s², moderate and severe between {ov['severe_crash'][0]:.1f} and {ov['moderate_crash'][1]:.1f}). "
          "This construction explains the near-perfect scores reported in Chapter 8 and is the most important thing to remember when reading them."),
        P(f"**Split.** `train_test_split(test_size=0.2, random_state=42, stratify=accident)` gives {F.N_TRAIN:,} training and {F.N_TEST:,} test events, of which {F.DET['confusion'][1][0] + F.DET['confusion'][1][1]} are crashes in the test part "
          f"({F.SEVM['per_class']['Minor']['support']} minor, {F.SEVM['per_class']['Moderate']['support']} moderate, {F.SEVM['per_class']['Severe']['support']} severe). There is no separate validation set and no cross-validation in the shipped script; "
          "the five-seed repeat of Chapter 8 compensates by regenerating the data and the split five times."),
        P("**Contrast with the base paper.** The base paper's data are proprietary police-reported records from one Chinese city (Dongguan, 2019 to 2023): 30,442 crashes split 19,483 / 4,871 / 6,088, with driver, vehicle, road and environment attributes and three severity targets "
          f"[{R['base']}]. The two datasets differ in origin (real versus generated), unit (a recorded crash versus a sensor event), features and labels, so no score on one can be compared with a score on the other."),
    ]


def preprocessing():
    return [
        H2("6.3 Features and Preprocessing"),
        P("A reading carries nine raw channels; two magnitudes are derived and the jerk is made non-negative, giving eleven features in a fixed order that is stored in `feature_names.pkl` so that training and serving can never disagree on column order."),
        TAB("The eleven features", ["No.", "Feature", "Unit", "Meaning", "Raw or derived"],
            [["1-3", "`acc_x`, `acc_y`, `acc_z`", "m/s²", "accelerometer axes; `acc_z` is about 9.81 at rest", "raw"],
             ["4", "`acc_magnitude`", "m/s²", "length of the acceleration vector", "derived (or supplied by the client)"],
             ["5-7", "`gyro_x`, `gyro_y`, `gyro_z`", "rad/s", "gyroscope axes (angular velocity)", "raw"],
             ["8", "`gyro_magnitude`", "rad/s", "length of the angular-velocity vector", "derived (or supplied)"],
             ["9", "`speed_before`", "km/h", "speed before the event (GPS)", "raw"],
             ["10", "`speed_change`", "km/h", "change in speed over the event; negative = slowing", "raw"],
             ["11", "`jerk`", "not stated in code", "rate of change of acceleration", "raw, absolute value taken"]],
            widths=[0.5, 1.7, 0.7, 2.4, 1.2], size=9),
        P("**Steps applied to every request** (`build_feature_vector`): each field is read as a float; a missing `acc_z` defaults to 9.81 and every other missing field to 0, so an empty payload becomes a calm, stationary reading; "
          "`acc_magnitude` and `gyro_magnitude` are computed when the client does not supply them; `jerk` is replaced by its absolute value; and the values are arranged in the stored order. "
          "The React manual form sends the three accelerations, the gyroscope magnitude (carried on `gyro_z`, with `gyro_x` and `gyro_y` set to zero) and the three motion fields, and computes `acc_magnitude` itself."),
        P(f"**Scaling.** A `StandardScaler` is fitted on the {F.N_TRAIN:,} training rows and applied unchanged to the test rows and to every request, so that the test and serving data cannot influence the statistics. "
          "Random forests do not need scaling, and the scaler does not change their splits; it is kept because the pickled models were trained on scaled inputs and because it lets the logistic-regression baseline run on the same matrix."),
        P(f"**Class imbalance.** About one event in five is a crash and one in twenty is Severe or Moderate. Instead of resampling, both forests use `class_weight='balanced'`, which weights each class by the inverse of its frequency. "
          f"The base paper instead applies SMOTE with one neighbour to the training part [{R['base']}, {R['smote']}]; the two approaches have the same aim, and on this separable data the difference would not be measurable."),
        P("**What is not done.** There is no outlier clipping, no missing-value imputation beyond the defaults, no filtering of a raw accelerometer trace and no windowing: a reading is already a summary of an event. "
          "Turning a stream of raw 50 Hz samples into these summaries, and deciding when an event begins, is a necessary stage of a real smartphone application that this project did not build (Chapter 10)."),
    ]


def algorithm_choice():
    b = F.BASE
    names = [("rule_based_fallback (acc_magnitude < 15 / 28 / 45)", "Rule thresholds on acc_magnitude"), ("logistic_regression", "Logistic regression"), ("decision_tree (depth 10)", "Decision tree, depth 10"),
             ("hist_gradient_boosting", "Histogram gradient boosting"), ("random_forest (ResQAI, retrained)", "**Random forest (ResQAI)**")]
    rows = []
    for k, label in names:
        r = b[k]
        rows.append([label, f"{r['det_accuracy']:.4f}", f"{r['det_f1']:.4f}", f"{r['det_false_alarm'] * 100:.2f}%", f"{r['sev_accuracy']:.4f}", f"{r['sev_macro_f1']:.4f}"])
    return [
        H2("6.4 Algorithm Choice and Justification"),
        P(f"**What was chosen.** Two random forests [{R['breiman']}] trained with scikit-learn [{R['sklearn']}]: a detector with 200 trees of depth at most 10 and a severity model with 250 trees of depth at most 12. "
          "A random forest averages many decision trees, each grown on a bootstrap sample with a random subset of features at every split; it handles features on different scales, captures interactions such as *large acceleration and large speed drop*, gives a probability that is used as the confidence, and exposes feature importances."),
        P("**Why not a deep model.** The base paper's FT-Transformer turns every feature into a token and applies self-attention " + f"[{R['gorishniy']}], and weights its three tasks with learned uncertainties [{R['kendall']}]. "
          "That machinery pays off on tens of thousands of heterogeneous, categorical-rich crash records. Here the input is eleven numeric channels with a clear physical meaning, the dataset is generated, and the deployment target is a phone or a small server; "
          "a transformer would add training cost, a larger artefact and a dependency on a deep-learning runtime without a measurable gain. The multi-task idea is kept in a simpler form: two models that share one scaler and one feature vector, joined by the gate."),
        P("**What the comparison shows.** To test whether the choice is justified, four alternatives were trained on the same split with the same scaled features. For the severity rows the detector gate is applied to every model, as in the application."),
        TAB("Random forest against simpler models on the 2,400 held-out events", ["Model", "Detector accuracy", "Detector F1", "False alarms", "Severity accuracy", "Severity macro-F1"], rows,
            widths=[2.0, 0.85, 0.8, 0.75, 0.9, 0.9], align=["l", "r", "r", "r", "r", "r"], size=8.5),
        P("Every model detects crashes perfectly, including the three-line threshold rule, which confirms that detection is not a hard problem on this data. The learned models earn their place on severity: the threshold rule loses about two and a half points of accuracy and almost nine points of macro-F1, "
          "while the forest, the tree and the boosted model are within a fraction of a point of each other and the histogram gradient-boosting model ties the forest. "
          "The forest is therefore a reasonable choice, not a uniquely best one; its advantages are the calibrated-looking probability, the absence of tuning and the interpretability, and a fair summary is that a boosted model or a decision tree would have served as well."),
    ]


def maths():
    return [
        H2("6.5 Mathematical Formulation"),
        P("The quantities that the code computes are listed here in the order of the pipeline. With accelerations (aₓ, a_y, a_z) in m/s² and angular velocities (ωₓ, ω_y, ω_z) in rad/s, the derived features are"),
        EQ("a = √(aₓ² + a_y² + a_z²)        ω = √(ωₓ² + ω_y² + ω_z²)        j = |j_raw|"),
        P("At rest only gravity acts, so a is about 9.81 m/s² and ω is about zero; the generator's normal-driving events have a between 8.7 and 10.9 m/s². Every feature xᵢ is then standardised with the training mean and standard deviation,"),
        EQ("zᵢ = (xᵢ − μᵢ) / σᵢ,      i = 1 … 11"),
        P("A decision tree chooses, at each node, the feature and threshold that most reduce the Gini impurity of the class proportions pₖ in the node,"),
        EQ("G(t) = 1 − Σₖ pₖ²,      ΔG = G(parent) − (n_L/n) G(L) − (n_R/n) G(R)"),
        P("With balanced class weights each training row of class c carries the weight w_c = n / (K · n_c), where n is the number of rows, K the number of classes and n_c the size of class c. "
          "A forest of T trees averages the class probabilities of its trees, so the detector's confidence is"),
        EQ("P(accident | z) = (1/T) Σₜ pₜ(1 | z),   T = 200,      â = 1 if P(accident | z) ≥ 0.5"),
        P("and the severity model returns the grade with the largest averaged probability over its T′ = 250 trees,"),
        EQ("ŝ = argmaxₖ (1/T′) Σₜ p′ₜ(k | z),      k ∈ {0 None, 1 Minor, 2 Moderate, 3 Severe}"),
        P("The detector gate, which is the only rule linking the two models, and the alert rule applied by the browser are"),
        EQ("s* = 0 if â = 0, otherwise ŝ;        alert ⇔ s* ≥ 2"),
        P(f"When the model files are missing the fallback assigns s* from fixed bands of the acceleration magnitude, 0 below 15, 1 below 28, 2 below 45 and 3 otherwise, with confidences 0.05, 0.6, 0.8 and 0.95. "
          f"To rank hospitals the server uses the haversine great-circle distance [{R['haversine']}] between the crash position (φ₁, λ₁) and each hospital (φ₂, λ₂), with the Earth radius R = 6,371 km,"),
        EQ("h = sin²(Δφ/2) + cos φ₁ cos φ₂ sin²(Δλ/2),      d = 2R · arcsin(√h)"),
        P("and returns the k smallest distances, rounded to two decimals (three are returned in an alert). Finally, the quantities reported in Chapter 8 are defined in the usual way from the counts of true and false positives and negatives,"),
        EQ("precision = TP/(TP+FP),   recall = TP/(TP+FN),   F1 = 2·precision·recall/(precision+recall),   false-alarm rate = FP/(FP+TN)"),
        P("The macro-F1 of the severity model is the unweighted mean of the four per-class F1 scores, so that the small Severe class counts as much as the large None class."),
    ]


